function sendRequest(method, url, headers, next){

    if(method === "post"){
        request.post(url, headers, function(err, response, body){

            return next(err, response, body);

        });
    }
    if(method === "get"){
        request.get(url, headers, function(err, response, body){

            return next(err, response, body);

        });
    }

}
